unsafe extern "C" fn palette_size(flags: DWORD) -> ::core::ffi::c_uint {
    match flags & (DDPCAPS_1BIT | DDPCAPS_2BIT | DDPCAPS_4BIT | DDPCAPS_8BIT) as DWORD {
        DDPCAPS_1BIT => return 2 as ::core::ffi::c_uint,
        DDPCAPS_2BIT => return 4 as ::core::ffi::c_uint,
        DDPCAPS_4BIT => return 16 as ::core::ffi::c_uint,
        DDPCAPS_8BIT => return 256 as ::core::ffi::c_uint,
        _ => return !(0 as ::core::ffi::c_uint),
    }
}
#[no_mangle]
pub unsafe extern "C" fn ddraw_palette_init(
    palette: *mut ddraw_palette,
    ddraw: *mut ddraw,
    flags: DWORD,
    entries: *mut PALETTEENTRY,
) -> HRESULT {
    let mut entry_count: ::core::ffi::c_uint = 0;
    let mut wined3d_flags: DWORD = 0 as DWORD;
    let mut hr: HRESULT = 0;

    entry_count = palette_size(flags);
    if entry_count == !(0 as ::core::ffi::c_uint) {
        WARN!("Invalid flags %#lx.\n", flags);
        return DDERR_INVALIDPARAMS as HRESULT;
    }

    if (flags & (DDPCAPS_8BITENTRIES as DWORD)) != 0 {
        wined3d_flags |= WINED3D_PALETTE_8BIT_ENTRIES as DWORD;
    }
    if (flags & (DDPCAPS_ALLOW256 as DWORD)) != 0 {
        wined3d_flags |= WINED3D_PALETTE_ALLOW_256 as DWORD;
    }
    if (flags & (DDPCAPS_ALPHA as DWORD)) != 0 {
        wined3d_flags |= WINED3D_PALETTE_ALPHA as DWORD;
    }

    (*palette).IDirectDrawPalette_iface.lpVtbl = (&raw const ddraw_palette_vtbl).cast_mut();
    (*palette).ref_ = 1 as LONG;
    (*palette).flags = flags;

    hr = wined3d_palette_create(
        (*ddraw).wined3d_device,
        wined3d_flags as u32,
        entry_count,
        entries,
        &raw mut (*palette).wined3d_palette,
    );
    if hr < (0 as HRESULT) {
        WARN!("Failed to create wined3d palette, hr %#lx.\n", hr);
        return hr;
    }

    (*palette).ddraw = ddraw;
    (*palette).ifaceToRelease = &raw mut (*ddraw).IDirectDraw7_iface as *mut IUnknown;
    IUnknown_AddRef((*palette).ifaceToRelease);

    return DD_OK as HRESULT;
}

